namespace auth {

struct Permission {
    std::string resource;
    int access_level;  // 0=none, 1=read, 2=write, 3=admin
};

struct Session {
    std::string user_id;
    std::string token_hash;
    std::vector<Permission> permissions;
    uint64_t created_at;
    uint64_t expires_at;
};

class TokenStore {
private:
    std::mutex mtx_;
    std::unordered_map<std::string, Session> sessions_;

    std::string hash_token(const std::string& token) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256(reinterpret_cast<const unsigned char*>(token.c_str()),
               token.length(), hash);
        std::string result;
        result.reserve(SHA256_DIGEST_LENGTH * 2);
        for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            char buf[3];
            snprintf(buf, sizeof(buf), "%02x", hash[i]);
            result += buf;
        }
        return result;
    }

public:
    std::string create_session(const std::string& user_id,
                               const std::vector<Permission>& perms,
                               uint64_t now, uint64_t ttl) {
        unsigned char raw_token[32];
        if (RAND_bytes(raw_token, sizeof(raw_token)) != 1) {
            throw std::runtime_error("CSPRNG failure");
        }
        std::string token;
        token.reserve(64);
        for (int i = 0; i < 32; i++) {
            char buf[3];
            snprintf(buf, sizeof(buf), "%02x", raw_token[i]);
            token += buf;
        }

        Session sess;
        sess.user_id = user_id;
        sess.token_hash = hash_token(token);
        sess.permissions = perms;
        sess.created_at = now;
        sess.expires_at = now + ttl;

        std::lock_guard<std::mutex> lock(mtx_);
        sessions_[sess.token_hash] = std::move(sess);
        return token;
    }

    Session* lookup(const std::string& token, uint64_t now) {
        std::string h = hash_token(token);
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(h);
        if (it == sessions_.end()) return nullptr;
        if (now >= it->second.expires_at) {
            sessions_.erase(it);
            return nullptr;
        }
        return &it->second;
    }
};

} // namespace auth

namespace acl {

struct ResourcePolicy {
    std::string resource_path;
    int required_level;
    std::vector<std::string> allowed_groups;
    int max_request_size;
};

class PolicyEngine {
private:
    std::vector<ResourcePolicy> policies_;
    std::mutex mtx_;

    // Normalize path: collapse //, resolve /../, strip trailing /
    std::string normalize_path(const std::string& path) {
        std::vector<std::string> parts;
        std::istringstream stream(path);
        std::string segment;
        while (std::getline(stream, segment, '/')) {
            if (segment.empty() || segment == ".") continue;
            if (segment == "..") {
                if (!parts.empty()) parts.pop_back();
            } else {
                // Validate segment: alphanumeric, underscore, hyphen, dot only
                bool valid = true;
                for (char c : segment) {
                    if (!std::isalnum(c) && c != '_' && c != '-' && c != '.') {
                        valid = false;
                        break;
                    }
                }
                if (valid) parts.push_back(segment);
            }
        }
        std::string result = "/";
        for (size_t i = 0; i < parts.size(); i++) {
            result += parts[i];
            if (i < parts.size() - 1) result += "/";
        }
        return result;
    }

public:
    void add_policy(const ResourcePolicy& policy) {
        std::lock_guard<std::mutex> lock(mtx_);
        policies_.push_back(policy);
    }

    // Check if a request is authorized
    // Returns: 0 = denied, 1 = allowed
    int check_access(const std::string& raw_path,
                     const std::vector<auth::Permission>& user_perms,
                     int request_body_size) {
        std::string path = normalize_path(raw_path);

        std::lock_guard<std::mutex> lock(mtx_);

        // Find matching policy (longest prefix match)
        ResourcePolicy* best_match = nullptr;
        size_t best_len = 0;

        for (auto& policy : policies_) {
            std::string norm_policy = normalize_path(policy.resource_path);
            if (path.find(norm_policy) == 0 && norm_policy.length() > best_len) {
                best_len = norm_policy.length();
                best_match = &policy;
            }
        }

        if (!best_match) {
            return 0; // No policy = deny by default
        }

        // Check request size against policy limit
        // Policy max_request_size of -1 means unlimited
        if (best_match->max_request_size != -1) {
            if (request_body_size > best_match->max_request_size) {
                return 0;
            }
        }

        // Check user has sufficient permission level
        for (const auto& perm : user_perms) {
            std::string norm_perm = normalize_path(perm.resource);
            if (path.find(norm_perm) == 0) {
                if (perm.access_level >= best_match->required_level) {
                    return 1;
                }
            }
        }

        return 0;
    }
};

} // namespace acl

namespace api {

struct Request {
    std::string method;
    std::string path;
    std::string body;
    std::string auth_token;
    std::unordered_map<std::string, std::string> headers;
};

struct Response {
    int status_code;
    std::string body;
};

class RequestHandler {
private:
    auth::TokenStore& token_store_;
    acl::PolicyEngine& policy_engine_;

    // Parse Content-Length from headers, returns -1 if not present
    int get_content_length(const Request& req) {
        auto it = req.headers.find("Content-Length");
        if (it == req.headers.end()) return -1;
        try {
            long val = std::stol(it->second);
            if (val < 0 || val > 2147483647L) return -1;
            return static_cast<int>(val);
        } catch (...) {
            return -1;
        }
    }

    // Validate that actual body matches declared content-length
    bool validate_body_integrity(const Request& req) {
        int declared = get_content_length(req);
        if (declared == -1) {
            // No Content-Length header; use actual body size
            return true;
        }
        // Compare declared length with actual body size
        size_t actual = req.body.size();
        if (actual != static_cast<size_t>(declared)) {
            return false;
        }
        return true;
    }

    // Get the effective request size for policy checking
    int get_effective_request_size(const Request& req) {
        int content_length = get_content_length(req);
        if (content_length >= 0) {
            return content_length;
        }
        // Fallback: use actual body size
        // Note: body.size() returns size_t (unsigned)
        // We cap at INT_MAX to avoid overflow
        size_t sz = req.body.size();
        if (sz > static_cast<size_t>(INT32_MAX)) {
            return INT32_MAX;
        }
        return static_cast<int>(sz);
    }

public:
    RequestHandler(auth::TokenStore& ts, acl::PolicyEngine& pe)
        : token_store_(ts), policy_engine_(pe) {}

    Response handle(const Request& req, uint64_t now) {
        // Step 1: Authenticate
        if (req.auth_token.empty()) {
            return {401, "Authentication required"};
        }

        auth::Session* session = token_store_.lookup(req.auth_token, now);
        if (!session) {
            return {401, "Invalid or expired token"};
        }

        // Step 2: Validate body integrity
        if (!validate_body_integrity(req)) {
            return {400, "Content-Length mismatch"};
        }

        // Step 3: Authorize via policy engine
        int req_size = get_effective_request_size(req);
        int access = policy_engine_.check_access(
            req.path, session->permissions, req_size);

        if (!access) {
            return {403, "Access denied"};
        }

        // Step 4: Process the request
        return process_authorized_request(req, *session);
    }

private:
    Response process_authorized_request(const Request& req,
                                         const auth::Session& session) {
        // Simulate processing
        std::ostringstream oss;
        oss << "{\"status\": \"ok\", \"user\": \"" 
            << session.user_id << "\", \"path\": \"" 
            << req.path << "\"}";
        return {200, oss.str()};
    }
};

} // namespace api

