int main(int argc, char* argv[]) {
    auth::TokenStore token_store;
    acl::PolicyEngine policy_engine;

    // Setup: admin resource requires level 3, max 1024 bytes
    acl::ResourcePolicy admin_policy;
    admin_policy.resource_path = "/admin";
    admin_policy.required_level = 3;
    admin_policy.max_request_size = 1024;
    policy_engine.add_policy(admin_policy);

    // Setup: public resource requires level 1, max 4096 bytes
    acl::ResourcePolicy public_policy;
    public_policy.resource_path = "/api/public";
    public_policy.required_level = 1;
    public_policy.max_request_size = 4096;
    policy_engine.add_policy(public_policy);

    // Create a test user with read-only access to /api/public
    std::vector<auth::Permission> user_perms = {
        {"/api/public", 1}
    };
    std::string token = token_store.create_session("testuser", user_perms,
                                                    1000, 3600);

    // Simulate a request
    api::Request req;
    req.method = "POST";
    req.path = "/api/public/data";
    req.auth_token = token;
    req.body = std::string(5000, 'A'); // 5000 byte body
    req.headers["Content-Length"] = "-2"; // Attacker-controlled header

    api::RequestHandler handler(token_store, policy_engine);
    api::Response resp = handler.handle(req, 1500);

    std::cout << "Status: " << resp.status_code << std::endl;
    std::cout << "Body: " << resp.body << std::endl;

    return 0;
}
